/* MCN docs app. Pages come from pages.js (generated by website/build_docs.py from
   docs/pages/*.md); routes are hashes: #/group/page, or #/group/page#heading. */
(function () {
  "use strict";
  var DOCS = window.MCN_DOCS;
  var REPO = "https://github.com/LeninPrakash41/mcn/blob/main/website/docs/pages/";
  var $ = function (id) { return document.getElementById(id); };

  var order = [];                       // flat page list, in sidebar order
  DOCS.nav.forEach(function (g) { g.pages.forEach(function (slug) { order.push({ slug: slug, group: g.title }); }); });
  var DEFAULT = order[0].slug;

  // ── Sidebar ────────────────────────────────────────────────────────────
  var sidebar = $("sidebar");
  sidebar.innerHTML = DOCS.nav.map(function (g) {
    return '<div class="nav-group"><h2>' + g.title + "</h2><ul>" + g.pages.map(function (slug) {
      return '<li><a href="#/' + slug + '" data-slug="' + slug + '">' + DOCS.pages[slug].title + "</a></li>";
    }).join("") + "</ul></div>";
  }).join("");

  var menuBtn = document.querySelector(".menu-btn"), scrim = document.querySelector(".scrim");
  function setMenu(open) {
    sidebar.classList.toggle("open", open); scrim.hidden = !open;
    menuBtn.setAttribute("aria-expanded", String(open));
  }
  menuBtn.addEventListener("click", function () { setMenu(!sidebar.classList.contains("open")); });
  scrim.addEventListener("click", function () { setMenu(false); });

  // ── Rendering ──────────────────────────────────────────────────────────
  function slugify(text) {
    return text.toLowerCase().replace(/<[^>]+>/g, "").replace(/[`'"’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function parseHash() {
    var h = decodeURIComponent(location.hash.replace(/^#\/?/, ""));
    var parts = h.split("#");
    return { slug: parts[0] || DEFAULT, anchor: parts[1] || "" };
  }

  var tocObserver = null;

  function render() {
    var route = parseHash();
    var page = DOCS.pages[route.slug];
    if (!page) { location.replace("#/" + DEFAULT); return; }

    var article = $("article");
    article.innerHTML = marked.parse(page.md, { gfm: true });

    // Lead paragraph, heading ids + anchors, tables, callouts, card lists
    var h1 = article.querySelector("h1");
    if (h1 && h1.nextElementSibling && h1.nextElementSibling.tagName === "P") h1.nextElementSibling.classList.add("lead");
    var seen = {};
    article.querySelectorAll("h2, h3").forEach(function (h) {
      var id = slugify(h.textContent); if (seen[id]) id += "-" + (++seen[id]); else seen[id] = 1;
      h.id = id;
      var a = document.createElement("a"); a.className = "anchor"; a.href = "#/" + route.slug + "#" + id;
      a.textContent = "#"; a.setAttribute("aria-label", "Link to this section"); h.prepend(a);
    });
    article.querySelectorAll("table").forEach(function (t) {
      var w = document.createElement("div"); w.className = "table-wrap"; t.parentNode.insertBefore(w, t); w.appendChild(t);
    });
    article.querySelectorAll("blockquote").forEach(function (q) {
      var s = q.querySelector("p > strong:first-child");
      var kind = s && s.textContent.trim().toLowerCase().replace(/:$/, "");
      if (kind === "note" || kind === "tip" || kind === "warning") q.classList.add(kind);
    });
    var walker = document.createTreeWalker(article, NodeFilter.SHOW_COMMENT);
    while (walker.nextNode()) {
      if (walker.currentNode.nodeValue.trim() === "cards") {
        var next = walker.currentNode.nextSibling;
        while (next && next.nodeType !== 1) next = next.nextSibling;
        if (next && next.tagName === "UL") next.classList.add("cards");
      }
    }
    article.querySelectorAll('a[href^="http"]').forEach(function (a) { a.target = "_blank"; a.rel = "noopener"; });
    MCNSite.enhanceCode(article);

    // Chrome around the article
    var idx = order.findIndex(function (p) { return p.slug === route.slug; });
    var group = order[idx].group;
    document.title = page.title + " · MCN Docs";
    $("crumbs").innerHTML = '<a href="#/' + DEFAULT + '">Docs</a> / ' + group;
    $("edit-link").href = REPO + page.file;
    var prev = order[idx - 1], next = order[idx + 1];
    $("pager").innerHTML =
      (prev ? '<a class="prev" href="#/' + prev.slug + '"><small>← Previous</small>' + DOCS.pages[prev.slug].title + "</a>" : "") +
      (next ? '<a class="next" href="#/' + next.slug + '"><small>Next →</small>' + DOCS.pages[next.slug].title + "</a>" : "");
    sidebar.querySelectorAll("a").forEach(function (a) {
      if (a.dataset.slug === route.slug) { a.setAttribute("aria-current", "page"); }
      else a.removeAttribute("aria-current");
    });
    var current = sidebar.querySelector('[aria-current="page"]');
    if (current) {
      var r = current.getBoundingClientRect(), s = sidebar.getBoundingClientRect();
      if (r.top < s.top || r.bottom > s.bottom) current.scrollIntoView({ block: "center" });
    }
    setMenu(false);
    buildToc(article, route.slug);

    if (route.anchor && document.getElementById(route.anchor)) document.getElementById(route.anchor).scrollIntoView();
    else window.scrollTo(0, 0);
  }

  function buildToc(article, slug) {
    var heads = Array.prototype.slice.call(article.querySelectorAll("h2, h3"));
    var toc = $("toc");
    toc.innerHTML = heads.map(function (h) {
      var text = h.textContent.replace(/^#/, "");
      return '<li><a href="#/' + slug + "#" + h.id + '" data-id="' + h.id + '"' + (h.tagName === "H3" ? ' class="sub"' : "") + ">" + text + "</a></li>";
    }).join("");
    document.querySelector(".toc").style.visibility = heads.length ? "visible" : "hidden";
    if (tocObserver) tocObserver.disconnect();
    if (!heads.length || !("IntersectionObserver" in window)) return;
    var links = toc.querySelectorAll("a");
    function mark(id) { links.forEach(function (a) { a.classList.toggle("active", a.dataset.id === id); }); }
    mark(heads[0].id);
    tocObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) { if (e.isIntersecting) mark(e.target.id); });
    }, { rootMargin: "-72px 0px -70% 0px" });
    heads.forEach(function (h) { tocObserver.observe(h); });
  }

  // ── Search ─────────────────────────────────────────────────────────────
  var index = order.map(function (p) {
    var md = DOCS.pages[p.slug].md;
    var text = md.replace(/```[\s\S]*?```/g, function (b) { return b.replace(/```\w*/g, " "); })
                 .replace(/[#>*_`|[\]()-]+/g, " ").replace(/\s+/g, " ");
    return { slug: p.slug, group: p.group, title: DOCS.pages[p.slug].title, text: text,
             heads: (md.match(/^##+ .+$/gm) || []).map(function (h) { return h.replace(/^#+ /, ""); }) };
  });
  var modal = $("search"), input = $("search-input"), results = $("search-results"), selected = 0, hits = [];

  function escHtml(s) { return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  function highlightTerms(s, terms) {
    var out = escHtml(s);
    terms.forEach(function (t) { out = out.replace(new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig"), "<mark>$1</mark>"); });
    return out;
  }
  function search(q) {
    var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    return index.map(function (p) {
      var title = p.title.toLowerCase(), text = p.text.toLowerCase(), score = 0;
      for (var i = 0; i < terms.length; i++) {
        var t = terms[i], inText = text.indexOf(t);
        if (inText < 0 && title.indexOf(t) < 0) return null;
        score += (title.indexOf(t) >= 0 ? 10 : 0) + (p.heads.some(function (h) { return h.toLowerCase().indexOf(t) >= 0; }) ? 4 : 0) + 1;
      }
      var at = text.indexOf(terms[0]), start = Math.max(0, at - 50);
      var snip = (start ? "…" : "") + p.text.slice(start, start + 140).trim() + "…";
      var head = p.heads.find(function (h) { return h.toLowerCase().indexOf(terms[0]) >= 0; });
      return { p: p, score: score, snip: snip, anchor: head ? slugify(head) : "" };
    }).filter(Boolean).sort(function (a, b) { return b.score - a.score; }).slice(0, 8)
      .map(function (h) { h.terms = terms; return h; });
  }
  function drawResults() {
    if (!input.value.trim()) { results.innerHTML = '<li class="empty">Type to search every page</li>'; return; }
    if (!hits.length) { results.innerHTML = '<li class="empty">No results for “' + escHtml(input.value) + "”</li>"; return; }
    results.innerHTML = hits.map(function (h, i) {
      var href = "#/" + h.p.slug + (h.anchor ? "#" + h.anchor : "");
      return '<li role="option" aria-selected="' + (i === selected) + '"><a href="' + href + '"><span class="r-title">' +
        highlightTerms(h.p.title, h.terms) + '</span><span class="r-group">' + h.p.group + '</span><span class="r-snip">' +
        highlightTerms(h.snip, h.terms) + "</span></a></li>";
    }).join("");
  }
  function openSearch() { modal.hidden = false; input.value = ""; hits = []; selected = 0; drawResults(); input.focus(); }
  function closeSearch() { modal.hidden = true; }
  document.querySelector(".search-trigger").addEventListener("click", openSearch);
  input.addEventListener("input", function () { hits = search(input.value); selected = 0; drawResults(); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown") { selected = Math.min(selected + 1, hits.length - 1); drawResults(); e.preventDefault(); }
    else if (e.key === "ArrowUp") { selected = Math.max(selected - 1, 0); drawResults(); e.preventDefault(); }
    else if (e.key === "Enter" && hits[selected]) { results.querySelectorAll("a")[selected].click(); }
  });
  results.addEventListener("click", function (e) { if (e.target.closest("a")) closeSearch(); });
  modal.addEventListener("click", function (e) { if (e.target === modal) closeSearch(); });
  document.addEventListener("keydown", function (e) {
    var typing = /INPUT|TEXTAREA/.test(document.activeElement.tagName);
    if ((e.key === "k" && (e.metaKey || e.ctrlKey)) || (e.key === "/" && !typing)) { e.preventDefault(); openSearch(); }
    else if (e.key === "Escape") { closeSearch(); setMenu(false); }
  });
  if (!/Mac|iPhone|iPad/.test(navigator.platform)) document.querySelector(".search-trigger kbd").textContent = "Ctrl K";

  window.addEventListener("hashchange", render);
  render();
})();
